def countWetColumns(heights):
    n = len(heights)
    taller_left = [False] * n
    best = -1
    for i in range(n):
        taller_left[i] = best > heights[i]
        if heights[i] > best:
            best = heights[i]
    count = 0
    best = -1
    for i in range(n - 1, -1, -1):
        if taller_left[i] and best > heights[i]:
            count += 1
        if heights[i] > best:
            best = heights[i]
    return count
